import{_ as o,C as s,c as r,o as i,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Activity plans","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/activity-plans.md","filePath":"master/human-resources/employees/setup/activity-plans.md","lastUpdated":1792041590000}'),l={name:"master/human-resources/employees/setup/activity-plans.md"};function g(d,t,p,h,c,m){const a=s("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="activity-plans" tabindex="-1">Activity plans <a class="header-anchor" href="#activity-plans" aria-label="Permalink to &quot;Activity plans&quot;">​</a></h1><p>An activity plan is a checklist of tasks that you start for an employee in one click. A new hire needs the same steps each time: set up a laptop, plan training, hold a session. A plan stores those steps once. Each step is an activity template with a type, a person and a due time.</p><blockquote><p><strong>In simple words:</strong> A plan is a saved to-do list that you launch for an employee.</p></blockquote><p>Open <code>Employees → Configurations → Activity Plans</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Each template uses an <strong>Activity Type</strong> such as To-Do or Meeting. Activity types are managed in <code>Settings → General → Manage Activities</code>, under the <strong>Activity Types</strong> link. Aureus already includes Meeting, Exception, To-Do and Call. For how activities work, see <a href="./../../../getting-started/activities.html">Activities</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has two tabs: <strong>All</strong> and <strong>Archived</strong>. Columns are <strong>Name</strong>, <strong>Department</strong>, <strong>Manager</strong>, <strong>Company</strong> and <strong>Status</strong>.</p>',7)),n(a,{src:"/images1/employees/set_plans_list.png",alt:"Activity Plans list with All and Archived tabs showing the four plans, including Onboarding and Offboarding"}),t[1]||(t[1]=e('<p>Aureus includes four plans: <strong>Offboarding</strong>, <strong>Onboarding</strong>, <strong>Verification</strong> and <strong>Review Candidate</strong>. <strong>Offboarding</strong> has no department or company. Group the list by <strong>Name</strong>, <strong>Created By</strong>, <strong>Status</strong>, <strong>Created At</strong> or <strong>Updated At</strong>. Filter by <strong>Status</strong>.</p><h2 id="create-a-plan" tabindex="-1">Create a plan <a class="header-anchor" href="#create-a-plan" aria-label="Permalink to &quot;Create a plan&quot;">​</a></h2><ol><li>Open <code>Employees → Configurations → Activity Plans</code>.</li><li>Click <strong>New Activity Plan</strong>. A window opens.</li><li>Fill in <strong>General Information</strong>.</li></ol><ul><li><strong><em>Name:</em></strong> Required. For example <code>Warehouse Onboarding</code>.</li><li><strong><em>Department:</em></strong> Optional. Link the plan to one department.</li><li><strong><em>Company:</em></strong> Fills with your company.</li><li><strong><em>Status:</em></strong> On means the plan can be launched.</li></ul>',4)),n(a,{src:"/images1/employees/set_plan_form.png",alt:"Create Activity Plan window with the name Warehouse Onboarding"}),t[2]||(t[2]=e('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><h2 id="add-activity-templates" tabindex="-1">Add activity templates <a class="header-anchor" href="#add-activity-templates" aria-label="Permalink to &quot;Add activity templates&quot;">​</a></h2><p>A plan does nothing until it has templates. The <strong>View</strong> page shows the templates table without a create button. Click <strong>Edit</strong> on the plan. Under the form, find <strong>Activity Plan Templates</strong>. Click <strong>New activity plan template</strong>. <strong>Activity Type</strong> starts as <strong>Meeting</strong>.</p>',3)),n(a,{src:"/images1/employees/set_template_new.png",alt:"Create Activity Plan Template window with activity details, assignment and delay sections"}),t[3]||(t[3]=e('<h3 id="activity-details" tabindex="-1">Activity Details <a class="header-anchor" href="#activity-details" aria-label="Permalink to &quot;Activity Details&quot;">​</a></h3><ul><li><strong><em>Activity Type:</em></strong> Required. Pick To-Do, Meeting and so on.</li><li><strong><em>Summary:</em></strong> A short title for the task.</li><li><strong><em>Note:</em></strong> Longer instructions.</li></ul><h3 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h3><ul><li><strong><em>Assignment:</em></strong> Required. It decides who gets the task. The default is <strong>Ask at launch</strong>. Other options are <strong>Other</strong>, <strong>Coach</strong>, <strong>Manager</strong> and <strong>Employee</strong>.</li><li><strong><em>Assignee:</em></strong> Appears only when <strong>Assignment</strong> is <strong>Other</strong>. Pick a user.</li></ul><h3 id="delay-information" tabindex="-1">Delay Information <a class="header-anchor" href="#delay-information" aria-label="Permalink to &quot;Delay Information&quot;">​</a></h3><ul><li><strong><em>Delay Count:</em></strong> A number, 0 by default.</li><li><strong><em>Delay Unit:</em></strong> <strong>Minutes</strong>, <strong>Hours</strong>, <strong>Days</strong> or <strong>Weeks</strong>. Days by default.</li><li><strong><em>Delay From:</em></strong> <strong>Before Plan Date</strong> or <strong>After Plan Date</strong>.</li></ul><p>Click <strong>Create</strong> to save the template.</p><h2 id="example-the-onboarding-plan" tabindex="-1">Example: the Onboarding plan <a class="header-anchor" href="#example-the-onboarding-plan" aria-label="Permalink to &quot;Example: the Onboarding plan&quot;">​</a></h2><p>The <strong>Onboarding</strong> plan belongs to the Management department. It has three templates. All use the <strong>To-Do</strong> type, are assigned to the <strong>Manager</strong>, and have a delay of 0 days before the plan date.</p><table tabindex="0"><thead><tr><th>Summary</th><th>Type</th><th>Assignment</th></tr></thead><tbody><tr><td>Setup IT Materials</td><td>To-Do</td><td>Manager</td></tr><tr><td>Plan Training</td><td>To-Do</td><td>Manager</td></tr><tr><td>Training</td><td>To-Do</td><td>Manager</td></tr></tbody></table>',10)),n(a,{src:"/images1/employees/set_plan_templates.png",alt:"Onboarding activity plan listing the templates Setup IT Materials, Plan Training and Training"}),t[4]||(t[4]=e('<p>Click <strong>View</strong> on a plan to see these templates with their <strong>Assigned To</strong>, <strong>Interval</strong>, <strong>Delay Unit</strong> and <strong>Delay From</strong>. The table shows raw values such as <code>Assignment manager</code>, <code>days</code> and <code>before_plan_date</code>. <strong>Assigned To</strong> is blank.</p><h2 id="launch-a-plan-for-an-employee" tabindex="-1">Launch a plan for an employee <a class="header-anchor" href="#launch-a-plan-for-an-employee" aria-label="Permalink to &quot;Launch a plan for an employee&quot;">​</a></h2><ol><li>Open the employee. See <a href="./../employees/employee-profile.html">Employee profile</a>.</li><li>Click the blue <strong>Chatter</strong> icon button with the count badge in the page header. A side panel opens.</li><li>Click <strong>Schedule Activity</strong>. A window opens.</li><li>Choose the plan in <strong>Activity Plan</strong>.</li><li>Check the other fields: <strong>Activity Type</strong> (required), <strong>Due Date</strong>, <strong>Summary</strong>, <strong>Assigned To</strong> (required) and <strong>Body</strong>.</li><li>Click <strong>Schedule</strong>, or <strong>Cancel</strong> to leave.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create one plan per situation, such as onboarding and leaving. Keep each plan short.</p></div><h2 id="edit-archive-and-restore" tabindex="-1">Edit, archive and restore <a class="header-anchor" href="#edit-archive-and-restore" aria-label="Permalink to &quot;Edit, archive and restore&quot;">​</a></h2><p>Click <strong>Edit</strong> to change a plan or its templates. Click <strong>Delete</strong> to archive it. Use <strong>Restore</strong> on the <strong>Archived</strong> tab to bring it back.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./skill-types.html">Skill types</a></li><li><a href="./../employees/employee-profile.html">Employee profile</a></li><li><a href="./../../../getting-started/chatter.html">Chatter</a></li></ul>',8))])}const _=o(l,[["render",g]]);export{y as __pageData,_ as default};
